import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
experiment_data = np.load(
    os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
).item()

for dataset_name, data in experiment_data.items():
    print(f"\n===== Dataset: {dataset_name} =====")

    # Top-level final metric
    gen_success = data.get("generative_activation_success_rate", None)
    if gen_success is not None:
        print(f"Overall SAGE generative activation success rate: {gen_success:.4f}")

    summary = data.get("summary", {})

    # Overall metrics
    if "OVERALL" in summary:
        ov = summary["OVERALL"]
        print(f"\n-- OVERALL (n={ov['n']}) --")
        print(
            f"Neuronpedia generative accuracy: {ov['np_gen']['mean']:.4f} ± {ov['np_gen']['ci']:.4f}"
        )
        print(
            f"Neuronpedia predictive accuracy (correlation): {ov['np_pred']['mean']:.4f} ± {ov['np_pred']['ci']:.4f}"
        )
        print(
            f"SingleShot GPT baseline generative accuracy: {ov['ss_gen']['mean']:.4f} ± {ov['ss_gen']['ci']:.4f}"
        )
        print(
            f"SingleShot GPT baseline predictive accuracy (correlation): {ov['ss_pred']['mean']:.4f} ± {ov['ss_pred']['ci']:.4f}"
        )
        print(
            f"SAGE generative accuracy: {ov['sage_gen']['mean']:.4f} ± {ov['sage_gen']['ci']:.4f}"
        )
        print(
            f"SAGE predictive accuracy (correlation): {ov['sage_pred']['mean']:.4f} ± {ov['sage_pred']['ci']:.4f}"
        )

    # Per-layer metrics
    for k, v in summary.items():
        if k == "OVERALL":
            continue
        print(f"\n-- Layer {k} (n={v['n']}) --")
        print(
            f"Neuronpedia generative accuracy: {v['np_gen']['mean']:.4f} ± {v['np_gen']['ci']:.4f}"
        )
        print(
            f"Neuronpedia predictive accuracy (correlation): {v['np_pred']['mean']:.4f} ± {v['np_pred']['ci']:.4f}"
        )
        print(
            f"SingleShot GPT baseline generative accuracy: {v['ss_gen']['mean']:.4f} ± {v['ss_gen']['ci']:.4f}"
        )
        print(
            f"SingleShot GPT baseline predictive accuracy (correlation): {v['ss_pred']['mean']:.4f} ± {v['ss_pred']['ci']:.4f}"
        )
        print(
            f"SAGE generative accuracy: {v['sage_gen']['mean']:.4f} ± {v['sage_gen']['ci']:.4f}"
        )
        print(
            f"SAGE predictive accuracy (correlation): {v['sage_pred']['mean']:.4f} ± {v['sage_pred']['ci']:.4f}"
        )

    # Final validation loss (last entry)
    val_losses = data.get("losses", {}).get("val", [])
    if val_losses:
        print(
            f"\nFinal per-feature validation loss (1 - SAGE gen_acc) mean: {np.mean(val_losses):.4f}"
        )
        print(
            f"Final per-feature validation loss (1 - SAGE gen_acc) last: {val_losses[-1]:.4f}"
        )

    # Deltas
    if "OVERALL" in summary:
        ov = summary["OVERALL"]
        print(
            f"\nDelta SAGE - Neuronpedia (generative accuracy): {ov['sage_gen']['mean'] - ov['np_gen']['mean']:+.4f}"
        )
        print(
            f"Delta SAGE - Neuronpedia (predictive accuracy): {ov['sage_pred']['mean'] - ov['np_pred']['mean']:+.4f}"
        )
        print(
            f"Delta SAGE - SingleShot (generative accuracy): {ov['sage_gen']['mean'] - ov['ss_gen']['mean']:+.4f}"
        )
        print(
            f"Delta SAGE - SingleShot (predictive accuracy): {ov['sage_pred']['mean'] - ov['ss_pred']['mean']:+.4f}"
        )

